const schule = "HTL";
let punkte = 10;
punkte = punkte + 5;
console.log(punkte);   // 15

let x;
console.log(x);    // undefined

console.log(typeof 42);    // number
console.log(typeof "42");  // string
console.log(typeof true);  // boolean

const note = 2;
if (note === 1) {
  console.log("Sehr gut");
} else if (note <= 4) {
  console.log("Bestanden");
} else {
  console.log("Nicht genügend");
}
// Bestanden

for (let i = 1; i <= 3; i++) {
  console.log("Runde " + i);
}

let n = 1;
while (n < 100) {
  n = n * 2;
}
console.log(n);  // 128

const noten = [2, 1, 3];
noten.push(4);
console.log(noten.length); // 4
console.log(noten[0]);     // 2
console.log(noten[4]);  // undefined

function schnitt(liste) {
  let summe = 0;
  for (const n of liste) {
    summe += n;
  }
  return summe / liste.length;
}
console.log(schnitt(noten)); // 2.5

const doppelt = (x) => x * 2;
console.log(doppelt(21));    // 42

